insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-routine-takes-next-free-number-s713','decision','The routine takes the next free session number','S713 conductor: handoff 704 named the routine''s next session SkyKittiwake, Session 704, but Sam''s plain sessions took 705 to 712, so the 06:12Z firing of 2026-11-23 ran as S713 and wrote handoff 714. The routine''s next session takes the next free number at its start and writes the handoff one above the highest on main; a plain session follows the newest plain-session handoff.',array['conductor','queue','numbering','handoff'],'proposed','docs/session_714_handoff.md; #3704','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-peralta-load-cleans-labels-first-s713','decision','Peralta''s outline load cleans label lines first','S713 conductor: the dry run of Peralta''s read 45031089800 filed label lines as outcomes, so a load-time clean at the lan folder only (a leading colon, the SCANS framework run, a bare Part N heading, placeholder lines, curriculum-system notes) went ahead of the load, which would have filed wrong rows. The filed read and the recall gates are unchanged. Load 45127831747: 3,731 rows.',array['course-outcomes','peralta','outline-load'],'proposed','#3684; load 45127831747','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-ge-steps-three-colleges-s713','decision','Three general education reconcile steps','S713 conductor, on the 11 of S703''s 21 general education holds outside lane 1''s colleges: Las Positas''s two LPC-GE steps widened; Antelope Valley''s general education plus electives to reach 60 fill, only where the figure is the degree total less the major''s; College of Marin''s 22-to-34 range; free reconcile runs. 8 records pass (#3707). Antelope Valley 43028 and De Anza 45499 go to a person.',array['program-requirements','general-education','reconcile','las-positas','antelope-valley','college-of-marin'],'proposed','#3707; migrate 45147953792','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-ge-01037-held-double-count-s713','decision','Las Positas 01037 held: it passes only by double counting','S713 conductor, after #3707''s second reader: Las Positas 01037 passes the general education step only by double counting, 28 units against 26-27, so it left the plan, and its committed file takes main''s record back so the college''s next reread cannot post the passing record and undo the hold.',array['program-requirements','las-positas','general-education','held'],'proposed','#3707','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-plan-rows-change-a-verdict-s713','decision','A plan writes only rows that change a verdict','S713 conductor: Las Positas 09227 (59-61 against 60) and Antelope Valley 39295 (57-63 against 60) took the general education units and still fail, so a full-row rewrite would change no verdict. They left #3707''s plan, its receipt lists them, and the college''s next reread posts their committed records. Each of #3707''s rows moves a record from failing to passing.',array['program-requirements','guarded-update','plans'],'proposed','#3707','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-srjc-cut-off-holds-two-s713','decision','Santa Rosa Junior 06566 and 32298 held from section_cut_off','S713 conductor, after #3705''s second reader: Natural Resources 06566 (its sibling 21718 reads the same table and passes) and Elementary Teacher Education 32298 (it already reaches its 33.5) are held, since the gap names the wrong cause. _short_or_unread counts incomplete only where a partial sum and a printed total are both read and the sum falls short. The plan went to 15 rows.',array['program-requirements','santa-rosa-junior','named-gaps','section-cut-off'],'proposed','#3705; migrate 45131380266','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-glendale-minors-before-apply-s713','decision','Glendale''s reader minors fixed before the apply','S713 conductor: Glendale''s second reader said apply, with three latent minors (a heading figure equal to the total zeroing a list that cannot be added, a bare word figure read as units, a substitute heading matching the negation Do not select from this list). They were fixed first, the 13 after-images proven unchanged (bc6e4a78); migrate 45148301846 then applied 13 of 13.',array['program-requirements','glendale','wording-rules','guarded-update'],'proposed','claude/s713-piles2; migrate 45148301846','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-ccsf-45768-existing-gap-s713','decision','An existing gap that fits is filed: City College of San Francisco 45768','S713 conductor: City College of San Francisco''s Cal-GETC 45768 bound on its own page but read below half the state''s course list. The census''s existing ge_pattern_certificate gap already names it by title, so it is filed there (no_record_s713.json) and not held for a new rule; it has no record and carries no record scores.',array['program-requirements','ccsf','named-gaps','general-education'],'proposed','claude/slo-ccsf 270a617a','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-ccsf-one-pr-s713','decision','City College of San Francisco''s work rides one PR','S713 conductor: City College of San Francisco''s outline read (claude/slo-ccsf) and its 53 page-finding programs (claude/ccsf-pages-s713) merge as one branch and one PR, one CI and merge cycle in place of two while the open-PR count sits at the cap. Its .run and .load stay at main''s value.',array['conductor','merge-order','ccsf'],'proposed','claude/slo-ccsf 34f7f05a','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('d-cancel-merge-push-page-read-s713','decision','A redundant page read started by a merge push is canceled','S713 conductor: #3675''s merge push to main started a college page read (45128802291) that reread #3686''s 11 plans, already filed. It was canceled as redundant.',array['conductor','workflows','page-read'],'proposed','run 45128802291','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('p-compact-preread-by-md5-s713','procedure','A compact pre-read compares md5 hashes','S713: #3705''s committed pre-read carries 72 KB of before-values. Hashing them on a local Postgres 16 (pg_ctlcluster 16 main) and comparing md5(record::text) of the live rows cut the read to 2 KB and matched 15 of 15. #3707''s and Glendale''s pre-reads ran the same way, the functions they call recreated locally from pg_get_functiondef.',array['supabase','guarded-update','pre-read','rule-10'],'proposed','kb/migrations/2026-11-23_s713_prreq_piles_preread.sql; docs/program_requirements_harvest_lessons.md S713','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('p-shared-shallow-clone-reshallows-s713','pitfall','Workers share one shallow clone''s history','S713: the workers'' checkouts share the shallow clone''s object store, so one worker''s --depth fetch shortened another''s history mid-build. Fetch a branch by name with --shallow-since or --deepen, never --depth. S691''s p-shared-git-shallow-lock-s691 is the same store''s lock.',array['git','workers','conductor'],'proposed','docs/reference/conductor_mode.md S713','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('p-confirm-verdict-marks-checked-at-apply-s713','pitfall','A prior confirm can mark an applied row checked','S713, #3705''s second reader: a confirm verdict whose fingerprint matches the new record marks the row checked as the apply writes it, and the rollback then skips that row. Each pre-read counts confirm_matches (on a full-row rewrite also the confirms carried from the old record, Sheet 82 card 1), and the apply aborts unless both are 0.',array['program-requirements','guarded-update','verdicts','rollback'],'proposed','#3705; #3707','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('p-claim-check-reads-current-capture-s713','pitfall','The claim check reads today''s capture','S713, #3705''s second reader: a named gap''s claim check reads sources.json, today''s capture, never the read behind the record, so it cannot fail a one- or two-page read or a sentence that names no page. Each receipt states the limit.',array['program-requirements','named-gaps','self-recall'],'proposed','#3705','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('p-bot-receipt-head-dispatch-js-tests-s713','procedure','A bot receipt head gets its test from a dispatch','S713: a branch that ends on the runner''s receipt commit starts no test (p-bot-receipt-head-runs-no-test-s697). Dispatching js-tests.yml on the branch ran test on that head: #3708''s 946b03ea, run 45148367921, green at 09:50Z, and #3708 merged. No empty commit is needed.',array['ci','merge-gate','js-tests'],'proposed','#3708; run 45148367921','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('m-collection-s713','milestone','S713''s collection: 42 records live, 47 named gaps','S713 (2026-11-23): 42 program records applied and live with no paid read: Santa Rosa Junior 15 (#3705), Las Positas 4 and Antelope Valley 4 (#3707), Glendale 13 and Clovis 6 (#3709; migrates 45148301846 and 45152118403). City College of San Francisco''s 53 page-finding programs: 47 named gaps, 6 held, $0.17 (#3710). Display build da3198af6b98 live, 18,660 rows. S703''s four PRs merged.',array['program-requirements','collection','display-build'],'proposed','#3705; #3707; #3708; #3709; #3710','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('m-outlines-s713','milestone','S713''s outlines: Peralta 3,731 rows, City College of San Francisco 3','S713 (2026-11-23): the four Peralta colleges'' outlines loaded (#3684, load 45127831747), 3,731 rows: Laney 663 SLO and 663 objective rows, Merritt 463 and 465, College of Alameda 365 and 368, Berkeley City 372 and 372. City College of San Francisco''s read 45128775065 loaded 3 new rows (load 45148533372); its other 1,416 match S690''s live rows.',array['course-outcomes','peralta','ccsf','outline-load'],'proposed','#3684; load 45127831747; load 45148533372','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23'),
('f-cobix-minors-s713','fact','For COBIx: the second readers'' minors from S713','S713, for COBIx: on #3705, a confirm on a cut-off row also blocks the apply, stricter than needed; Santa Rosa Junior 32301 and 35429 keep main''s live image while their files are rescored; the claim check''s limit is written only in the receipt. On #3707, College of Marin''s pattern reads a major''s 22 units on a constructed line (it moved nothing).',array['program-requirements','cobix','follow-up'],'proposed','#3705; #3707','SkyKittiwake (S713), the conductor',null,'SkyKittiwake (S713)',date '2026-11-23')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
